<script setup lang="ts">import{onMounted,ref}from'vue';import{Page}from'@vben/common-ui';import{ElMessage}from'element-plus';import{getPlatformSMSApi,savePlatformSMSApi}from'#/api/core/platform-sms';const config=ref(''),note=ref(''),loading=ref(false),saving=ref(false);async function load(){loading.value=true;try{const d=await getPlatformSMSApi();config.value=d.config;note.value=d.note}finally{loading.value=false}}async function save(){if(!config.value.trim()){ElMessage.warning('配置不能为空');return}saving.value=true;try{await savePlatformSMSApi(config.value.trim());ElMessage.success('短信配置已保存')}finally{saving.value=false}}onMounted(()=>void load());</script><template><Page title="短信配置" description="维护短信通道配置；当前仅保存配置，不会直接发送短信。"><el-card v-loading="loading" shadow="never"><el-alert :title="note" type="warning" :closable="false" class="mb-4"/><el-input v-model="config" :rows="14" type="textarea" placeholder="JSON 配置"/><div class="mt-4 flex justify-end"><el-button @click="load">重置</el-button><el-button :loading="saving" type="primary" @click="save">保存配置</el-button></div></el-card></Page></template>
